[Better Approach] Prime Count in Factorial ApproachFactorize k into its prime components, then for each prime, naively count its total occurrences in n! by checking every number from 1 to n.Finally, compute how many times k can divide n! by dividing the total count by the prime’s exponent in k.Step By Step ImplementationsSince final rem = 0, the number 2911285 is divisible by 13.Factorize the number k into its prime factors with their respective exponents.For each prime factor p of k, iterate from 1 to n.For each number i from 1 to n, count how many times p divides i. → Keep a running total of how many times p appears in the factorization of n!.After counting, divide the total count of p by its exponent in k. → This gives how many times pexp (from k) can divide n!.Do      this for all prime factors of k, and take the minimum among these results. → That minimum is the largest power x such that kx divides n!.
            C++

    #include <iostream>
#include <vector>
#include <climits>

using namespace std;

// Function to compute the prime 
// factorization of a number 'num'
vector<vector<int>> primeFactors(int num) {
    vector<vector<int>> factors;

    // Count the number of times 2 divides 'num'
    int count = 0;
    while (num % 2 == 0) {
        num /= 2;
        count++;
    }
    if (count > 0) factors.push_back({2, count});

    // Check for odd factors starting from 3
    for (int i = 3; i * i <= num; i += 2) {
        count = 0;
        while (num % i == 0) {
            num /= i;
            count++;
        }
        if (count > 0) factors.push_back({i, count});
    }

    // If 'num' is still greater than 1, it's a prime number
    if (num > 1) factors.push_back({num, 1});

    return factors;
}

int maxKPower(int n, int k) {
    vector<vector<int>> factors = primeFactors(k);

    // Initialize result to maximum possible, we'll 
    // take the minimum across all primes
    int result = INT_MAX;

    // For each prime factor of k
    for (auto &factor : factors) {

        int prime = factor[0];
        int freqInK = factor[1];

        int count = 0;

        // Count how many times 'prime' appears 
        // in the factorization of n!
        for (int i = 1; i <= n; i++) {
            int x = i;

            // Count how many times 'prime' divides 
            // this particular number
            while (x % prime == 0) {
                count++;
                x /= prime;
            }
        }

        // Since k = prime^freqInK × ..., 
        // we divide the total count by freqInK
        result = min(result, count / freqInK);
    }

    return result;
}

int main() {

    int n = 10, k = 9;
    cout << maxKPower(n, k) << '\n'; 

    return 0;
}


